    private static class MoreTrades2
    {
        public static readonly IReadOnlyList<Trade> List =
        [
            new("trade-bike", "🚲", "sky",
                Txt.Of("Bicycle mechanics|Mecánica de bicicletas|Mécanique vélo|Mecànica de bicicletes"),
                Txt.Of("How a bicycle works and how to keep it safe: gears, brakes, tyres, chain and the check before every ride.|Cómo funciona una bicicleta y cómo mantenerla segura: marchas, frenos, ruedas, cadena y la revisión antes de cada salida.|Comment fonctionne un vélo et comment le garder sûr : vitesses, freins, pneus, chaîne et la vérification avant chaque sortie.|Com funciona una bicicleta i com mantenir-la segura: marxes, frens, rodes, cadena i la revisió abans de cada sortida."),
                Txt.Of("Wear a helmet, and ask an adult or a bike shop when a repair touches the brakes.|Usa casco y pide ayuda a un adulto o a un taller cuando una reparación toque los frenos.|Porte un casque et demande à un adulte ou à un atelier quand une réparation touche les freins.|Porta casc i demana ajuda a un adult o a un taller quan una reparació toqui els frens."),
                [
                    C("gears", "Gears and transmission|Marchas y transmisión|Vitesses et transmission|Marxes i transmissió", "The chain links the chainring (pedals) to a cog (rear wheel). Big chainring + small cog = hard gear and fast; small chainring + big cog = easy gear for climbing.|La cadena une el plato (pedales) con un piñón (rueda trasera). Plato grande + piñón pequeño = marcha dura y rápida; plato pequeño + piñón grande = marcha suave para subir.|La chaîne relie le plateau (pédales) à un pignon (roue arrière). Grand plateau + petit pignon = vitesse dure et rapide ; petit plateau + grand pignon = vitesse facile pour grimper.|La cadena uneix el plat (pedals) amb un pinyó (roda del darrere). Plat gran + pinyó petit = marxa dura i ràpida; plat petit + pinyó gran = marxa suau per pujar.", Area.Physics, "Physics: gear ratios and torque|Física: relaciones de transmisión y par|Physique : rapports de transmission et couple|Física: relacions de transmissió i parell"),
                    C("brakes", "Brakes|Frenos|Freins|Frens", "Brakes turn movement into heat by friction. Pads must touch the rim or disc squarely; the front brake stops more, but squeeze both gently.|Los frenos convierten el movimiento en calor por rozamiento. Las zapatas deben tocar bien la llanta o el disco; el freno delantero frena más, pero aprieta los dos con suavidad.|Les freins transforment le mouvement en chaleur par frottement. Les patins doivent bien toucher la jante ou le disque ; le frein avant freine plus, mais serre les deux en douceur.|Els frens converteixen el moviment en calor per fregament. Les sabates han de tocar bé la llanda o el disc; el fre del davant frena més, però prem els dos amb suavitat.", Area.Physics, "Physics: friction and energy|Física: rozamiento y energía|Physique : frottement et énergie|Física: fregament i energia", "gears"),
                    C("tyres", "Tyres and punctures|Ruedas y pinchazos|Pneus et crevaisons|Rodes i punxades", "The right pressure (printed on the tyre, in bar or psi) makes riding easier and avoids pinch punctures; a puncture is found by putting the inflated tube in water and looking for bubbles.|La presión correcta (impresa en la cubierta, en bar o psi) hace pedalear más fácil y evita pellizcos; un pinchazo se encuentra metiendo la cámara inflada en agua y buscando burbujas.|La bonne pression (imprimée sur le pneu, en bar ou psi) rend le pédalage plus facile et évite les pincements ; on trouve une crevaison en mettant la chambre gonflée dans l'eau et en cherchant les bulles.|La pressió correcta (impresa a la coberta, en bar o psi) fa pedalar més fàcil i evita pessics; una punxada es troba posant la cambra inflada dins l'aigua i buscant bombolles.", Area.Physics, "Physics: air pressure|Física: presión del aire|Physique : pression de l'air|Física: pressió de l'aire", "gears"),
                    C("chain", "Chain and lubrication|Cadena y engrase|Chaîne et graissage|Cadena i greixatge", "A clean, oiled chain loses less energy and rusts less: clean it, put one drop of oil on each link, and wipe off the extra so it does not collect dirt.|Una cadena limpia y engrasada pierde menos energía y se oxida menos: límpiala, pon una gota de aceite en cada eslabón y quita el sobrante para que no acumule suciedad.|Une chaîne propre et huilée perd moins d'énergie et rouille moins : nettoie-la, mets une goutte d'huile sur chaque maillon et essuie le surplus pour qu'elle n'accumule pas la saleté.|Una cadena neta i greixada perd menys energia i s'oxida menys: neteja-la, posa una gota d'oli a cada baula i treu el sobrant perquè no acumuli brutícia.", Area.Chemistry, "Chemistry: rust is iron reacting with oxygen and water|Química: el óxido es hierro que reacciona con oxígeno y agua|Chimie : la rouille, c'est le fer qui réagit avec l'oxygène et l'eau|Química: el rovell és ferro que reacciona amb oxigen i aigua", "gears"),
                    C("check", "The safety check|La revisión de seguridad|La vérification de sécurité|La revisió de seguretat", "Before riding: A for air (tyres), B for brakes, C for chain and cranks, then quick releases closed, lights and bell. Speed = distance ÷ time.|Antes de salir: A de aire (ruedas), B de frenos (brakes), C de cadena y bielas, y después cierres rápidos cerrados, luces y timbre. Velocidad = distancia ÷ tiempo.|Avant de rouler : A pour l'air (pneus), B pour les freins (brakes), C pour la chaîne et les manivelles, puis serrages rapides fermés, éclairage et sonnette. Vitesse = distance ÷ temps.|Abans de sortir: A d'aire (rodes), B de frens (brakes), C de cadena i bieles, i després tancaments ràpids tancats, llums i timbre. Velocitat = distància ÷ temps.", Area.Mathematics, "Mathematics: speed, distance and time|Matemáticas: velocidad, distancia y tiempo|Mathématiques : vitesse, distance et temps|Matemàtiques: velocitat, distància i temps", "brakes", "tyres"),
                ],
                [
                    Q("gears", 1, "To climb a steep hill more easily, which combination do you choose?|Para subir una cuesta empinada con menos esfuerzo, ¿qué combinación eliges?|Pour monter une côte raide plus facilement, quelle combinaison choisis-tu ?|Per pujar una pujada forta amb menys esforç, quina combinació tries?", "Small chainring and big rear cog|Plato pequeño y piñón grande|Petit plateau et grand pignon|Plat petit i pinyó gran", "Each pedal turn moves the wheel less, so it needs less force.|Cada pedalada mueve menos la rueda, así que necesita menos fuerza.|Chaque tour de pédale fait moins tourner la roue, donc il faut moins de force.|Cada pedalada mou menys la roda, així que cal menys força.", "Big chainring and small cog|Plato grande y piñón pequeño|Grand plateau et petit pignon|Plat gran i pinyó petit", "It makes no difference|No cambia nada|Ça ne change rien|No canvia res", "Take air out of the tyres|Desinflar las ruedas|Dégonfler les pneus|Desinflar les rodes"),
                    Q("gears", 2, "A 48-tooth chainring drives a 16-tooth cog. How many times does the wheel turn per pedal turn?|Un plato de 48 dientes mueve un piñón de 16. ¿Cuántas vueltas da la rueda por cada pedalada?|Un plateau de 48 dents entraîne un pignon de 16. Combien de tours fait la roue par tour de pédale ?|Un plat de 48 dents mou un pinyó de 16. Quantes voltes fa la roda per cada pedalada?", "3", "48 ÷ 16 = 3 turns of the wheel.|48 ÷ 16 = 3 vueltas de rueda.|48 ÷ 16 = 3 tours de roue.|48 ÷ 16 = 3 voltes de roda.", "1", "32", "64"),
                    Q("gears", 3, "Why is it harder to pedal in a high gear when you start from a stop?|¿Por qué cuesta más arrancar en una marcha larga?|Pourquoi est-il plus dur de démarrer avec un grand braquet ?|Per què costa més arrencar amb una marxa llarga?", "You must push the bike further with each pedal turn, so it needs more force (torque)|Cada pedalada debe mover la bici más distancia, así que hace falta más fuerza (par)|Chaque tour de pédale doit faire avancer le vélo plus loin, il faut donc plus de force (couple)|Cada pedalada ha de moure la bici més distància, així que cal més força (parell)", "A long gear trades force for speed: good when you are already moving.|Una marcha larga cambia fuerza por velocidad: va bien cuando ya vas rápido.|Un grand braquet échange de la force contre de la vitesse : bien quand on roule déjà.|Una marxa llarga canvia força per velocitat: va bé quan ja vas ràpid.", "The chain is heavier|La cadena pesa más|La chaîne est plus lourde|La cadena pesa més", "The brakes are on|Los frenos están puestos|Les freins sont serrés|Els frens estan posats", "It is not harder|No cuesta más|Ce n'est pas plus dur|No costa més"),
                    Q("brakes", 1, "What do brakes turn the movement of the bike into?|¿En qué convierten los frenos el movimiento de la bici?|En quoi les freins transforment-ils le mouvement du vélo ?|En què converteixen els frens el moviment de la bici?", "Heat|Calor|Chaleur|Calor", "Friction between the pad and the rim or disc heats them up.|El rozamiento entre la zapata y la llanta o el disco los calienta.|Le frottement entre le patin et la jante ou le disque les chauffe.|El fregament entre la sabata i la llanda o el disc els escalfa.", "Light|Luz|Lumière|Llum", "Electricity|Electricidad|Électricité|Electricitat", "Nothing|Nada|Rien|Res"),
                    Q("brakes", 2, "Why should you not brake hard with only the front brake?|¿Por qué no se debe frenar fuerte solo con el freno delantero?|Pourquoi ne faut-il pas freiner fort seulement avec le frein avant ?|Per què no s'ha de frenar fort només amb el fre del davant?", "Your weight moves forward and you can go over the handlebars|Tu peso se va hacia delante y puedes salir por encima del manillar|Ton poids part vers l'avant et tu peux passer par-dessus le guidon|El teu pes va cap endavant i pots sortir per sobre del manillar", "Inertia keeps your body moving: brake with both, progressively.|La inercia mantiene tu cuerpo en movimiento: frena con los dos, poco a poco.|L'inertie garde ton corps en mouvement : freine avec les deux, progressivement.|La inèrcia manté el teu cos en moviment: frena amb els dos, de mica en mica.", "The front brake does not work|El freno delantero no funciona|Le frein avant ne marche pas|El fre del davant no funciona", "It wears the chain|Gasta la cadena|Il use la chaîne|Gasta la cadena", "It is always the best way|Siempre es lo mejor|C'est toujours le mieux|Sempre és el millor"),
                    Q("brakes", 3, "Why do rim brakes work worse in the rain?|¿Por qué los frenos de llanta funcionan peor con lluvia?|Pourquoi les freins sur jante marchent-ils moins bien sous la pluie ?|Per què els frens de llanda funcionen pitjor amb pluja?", "Water reduces the friction between pad and rim|El agua reduce el rozamiento entre zapata y llanta|L'eau réduit le frottement entre le patin et la jante|L'aigua redueix el fregament entre sabata i llanda", "Brake earlier and more gently when it is wet.|Frena antes y con más suavidad cuando está mojado.|Freine plus tôt et plus doucement quand c'est mouillé.|Frena abans i amb més suavitat quan està mullat.", "The rubber melts|La goma se derrite|Le caoutchouc fond|La goma es fon", "The cables shrink|Los cables encogen|Les câbles rétrécissent|Els cables s'encongeixen", "They work better|Funcionan mejor|Ils marchent mieux|Funcionen millor"),
                    Q("tyres", 1, "Where do you find the right pressure for a tyre?|¿Dónde encuentras la presión correcta de una rueda?|Où trouves-tu la bonne pression d'un pneu ?|On trobes la pressió correcta d'una roda?", "Printed on the side of the tyre|Impresa en el lateral de la cubierta|Imprimée sur le flanc du pneu|Impresa al lateral de la coberta", "It gives a minimum and maximum, in bar and psi.|Indica un mínimo y un máximo, en bar y psi.|Il indique un minimum et un maximum, en bar et en psi.|Indica un mínim i un màxim, en bar i psi.", "On the saddle|En el sillín|Sur la selle|Al seient", "There is none|No existe|Il n'y en a pas|No n'hi ha", "On the chain|En la cadena|Sur la chaîne|A la cadena"),
                    Q("tyres", 2, "How do you find a small hole in an inner tube?|¿Cómo encuentras un agujero pequeño en una cámara?|Comment trouves-tu un petit trou dans une chambre à air ?|Com trobes un forat petit en una cambra?", "Inflate it and put it in water: bubbles come out of the hole|Inflarla y meterla en agua: salen burbujas por el agujero|La gonfler et la mettre dans l'eau : des bulles sortent du trou|Inflar-la i posar-la dins l'aigua: surten bombolles pel forat", "The air under pressure escapes through the hole and makes bubbles.|El aire a presión escapa por el agujero y forma burbujas.|L'air sous pression s'échappe par le trou et fait des bulles.|L'aire a pressió s'escapa pel forat i fa bombolles.", "Smell it|Olerla|La sentir|Olorar-la", "Weigh it|Pesarla|La peser|Pesar-la", "Freeze it|Congelarla|La congeler|Congelar-la"),
                    Q("tyres", 3, "Why does a tyre with too little air puncture more easily on a kerb?|¿Por qué una rueda con poco aire se pincha más fácilmente al subir un bordillo?|Pourquoi un pneu pas assez gonflé crève-t-il plus facilement sur un trottoir ?|Per què una roda amb poc aire es punxa més fàcilment en pujar una vorera?", "The tube is pinched between the rim and the kerb|La cámara queda pellizcada entre la llanta y el bordillo|La chambre est pincée entre la jante et le trottoir|La cambra queda pessigada entre la llanda i la vorera", "It is called a pinch flat or 'snake bite': two small parallel holes.|Se llama pellizco o 'mordedura de serpiente': dos agujeritos paralelos.|On l'appelle pincement ou « morsure de serpent » : deux petits trous parallèles.|Es diu pessic o 'mossegada de serp': dos foradets paral·lels.", "Soft tyres are made of thinner rubber|Las ruedas blandas son de goma más fina|Les pneus mous sont en caoutchouc plus fin|Les rodes toves són de goma més fina", "Air attracts nails|El aire atrae los clavos|L'air attire les clous|L'aire atrau els claus", "It does not puncture more|No se pincha más|Il ne crève pas plus|No es punxa més"),
                    Q("chain", 1, "What happens to an unoiled chain left in the rain?|¿Qué le pasa a una cadena sin aceite que se queda bajo la lluvia?|Qu'arrive-t-il à une chaîne non huilée laissée sous la pluie ?|Què li passa a una cadena sense oli que es queda sota la pluja?", "It rusts|Se oxida|Elle rouille|S'oxida", "Iron + oxygen + water = rust; oil keeps the water away.|Hierro + oxígeno + agua = óxido; el aceite aparta el agua.|Fer + oxygène + eau = rouille ; l'huile éloigne l'eau.|Ferro + oxigen + aigua = rovell; l'oli aparta l'aigua.", "It gets longer|Se alarga|Elle s'allonge|S'allarga", "It changes colour to blue|Se vuelve azul|Elle devient bleue|Es torna blava", "Nothing|Nada|Rien|Res"),
                    Q("chain", 2, "After oiling a chain, why do you wipe off the extra oil?|Después de engrasar la cadena, ¿por qué se quita el aceite sobrante?|Après avoir huilé la chaîne, pourquoi essuie-t-on le surplus ?|Després de greixar la cadena, per què es treu l'oli sobrant?", "Extra oil collects dust and dirt that wear the chain|El aceite sobrante atrapa polvo y suciedad que gastan la cadena|Le surplus d'huile attrape la poussière et la saleté qui usent la chaîne|L'oli sobrant atrapa pols i brutícia que gasten la cadena", "Oil is needed inside the links, not on the outside.|El aceite hace falta dentro de los eslabones, no por fuera.|L'huile est utile dans les maillons, pas à l'extérieur.|L'oli cal dins les baules, no per fora.", "Oil is poisonous for the bike|El aceite es venenoso para la bici|L'huile est toxique pour le vélo|L'oli és verinós per a la bici", "It makes it rust|Hace que se oxide|Ça la fait rouiller|Fa que s'oxidi", "It is not necessary|No hace falta|Ce n'est pas nécessaire|No cal"),
                    Q("chain", 3, "Why do worn chains slip on the cogs?|¿Por qué una cadena gastada patina en los piñones?|Pourquoi une chaîne usée saute-t-elle sur les pignons ?|Per què una cadena gastada patina als pinyons?", "The links stretch and no longer fit the teeth|Los eslabones se estiran y ya no encajan en los dientes|Les maillons s'allongent et ne s'emboîtent plus dans les dents|Les baules s'estiren i ja no encaixen a les dents", "A chain checker measures this elongation; change the chain in time to save the cogs.|Un medidor de cadena mide este estiramiento; cámbiala a tiempo para salvar los piñones.|Un usuremètre mesure cet allongement ; change la chaîne à temps pour sauver les pignons.|Un mesurador de cadena mesura aquest estirament; canvia-la a temps per salvar els pinyons.", "It is too clean|Está demasiado limpia|Elle est trop propre|Està massa neta", "The tyres are flat|Las ruedas están desinfladas|Les pneus sont à plat|Les rodes estan desinflades", "The saddle is too high|El sillín está alto|La selle est trop haute|El seient és massa alt"),
                    Q("check", 1, "In the ABC check before riding, what does A stand for?|En la revisión ABC antes de salir, ¿qué significa la A?|Dans la vérification ABC avant de rouler, que veut dire le A ?|A la revisió ABC abans de sortir, què vol dir la A?", "Air: tyre pressure|Aire: la presión de las ruedas|Air : la pression des pneus|Aire: la pressió de les rodes", "Then B for brakes and C for chain and cranks.|Después B de frenos y C de cadena y bielas.|Puis B pour les freins et C pour la chaîne et les manivelles.|Després B de frens i C de cadena i bieles.", "Alarm|Alarma|Alarme|Alarma", "Adjust the saddle|Ajustar el sillín|Ajuster la selle|Ajustar el seient", "Accelerate|Acelerar|Accélérer|Accelerar"),
                    Q("check", 2, "You ride 15 km in 1 hour. What is your average speed?|Recorres 15 km en 1 hora. ¿Cuál es tu velocidad media?|Tu parcours 15 km en 1 heure. Quelle est ta vitesse moyenne ?|Recorres 15 km en 1 hora. Quina és la teva velocitat mitjana?", "15 km/h", "Speed = distance ÷ time = 15 ÷ 1.|Velocidad = distancia ÷ tiempo = 15 ÷ 1.|Vitesse = distance ÷ temps = 15 ÷ 1.|Velocitat = distància ÷ temps = 15 ÷ 1.", "1 km/h", "60 km/h", "150 km/h"),
                    Q("check", 3, "At 20 km/h, how many minutes do you need for 5 km?|A 20 km/h, ¿cuántos minutos necesitas para 5 km?|À 20 km/h, combien de minutes faut-il pour 5 km ?|A 20 km/h, quants minuts necessites per a 5 km?", "15 minutes|15 minutos|15 minutes|15 minuts", "5 ÷ 20 = 0.25 h = 15 min.|5 ÷ 20 = 0,25 h = 15 min.|5 ÷ 20 = 0,25 h = 15 min.|5 ÷ 20 = 0,25 h = 15 min.", "4 minutes|4 minutos|4 minutes|4 minuts", "25 minutes|25 minutos|25 minutes|25 minuts", "100 minutes|100 minutos|100 minutes|100 minuts"),
                ]),
            new("trade-painting", "🎨", "lavender",
                Txt.Of("Painting and decorating|Pintura y decoración|Peinture et décoration|Pintura i decoració"),
                Txt.Of("Paint a room like a professional: prepare the surface, mix colours, calculate the paint, apply it and decorate with light and colour.|Pinta una habitación como un profesional: prepara la superficie, mezcla colores, calcula la pintura, aplícala y decora con luz y color.|Peindre une pièce comme un professionnel : préparer la surface, mélanger les couleurs, calculer la peinture, l'appliquer et décorer avec la lumière et la couleur.|Pinta una habitació com un professional: prepara la superfície, barreja colors, calcula la pintura, aplica-la i decora amb llum i color."),
                Txt.Of("Ventilate the room, use a stable stepladder with an adult and never mix products without reading the label.|Ventila la habitación, usa una escalera estable con un adulto y nunca mezcles productos sin leer la etiqueta.|Aère la pièce, utilise un escabeau stable avec un adulte et ne mélange jamais des produits sans lire l'étiquette.|Ventila l'habitació, fes servir una escala estable amb un adult i no barregis mai productes sense llegir l'etiqueta."),
                [
                    C("prep", "Preparing the surface|Preparar la superficie|Préparer la surface|Preparar la superfície", "Paint sticks only to a clean, dry, smooth surface: fill holes, sand, dust off, protect with tape and apply primer on new or porous walls.|La pintura solo se agarra a una superficie limpia, seca y lisa: tapa agujeros, lija, quita el polvo, protege con cinta y da imprimación en paredes nuevas o porosas.|La peinture n'adhère qu'à une surface propre, sèche et lisse : rebouche les trous, ponce, dépoussière, protège avec du ruban et applique une sous-couche sur les murs neufs ou poreux.|La pintura només s'agafa a una superfície neta, seca i llisa: tapa forats, llima, treu la pols, protegeix amb cinta i dona imprimació a parets noves o poroses.", Area.Chemistry, "Chemistry: adhesion and porous materials|Química: adherencia y materiales porosos|Chimie : adhérence et matériaux poreux|Química: adherència i materials porosos"),
                    C("colour", "Mixing colours|Mezclar colores|Mélanger les couleurs|Barrejar colors", "With paints, primaries mix into secondaries: blue + yellow = green, red + yellow = orange, red + blue = violet. White makes a colour lighter (a tint).|Con pinturas, los primarios se mezclan en secundarios: azul + amarillo = verde, rojo + amarillo = naranja, rojo + azul = violeta. El blanco aclara un color.|Avec la peinture, les primaires donnent les secondaires : bleu + jaune = vert, rouge + jaune = orange, rouge + bleu = violet. Le blanc éclaircit une couleur.|Amb pintures, els primaris es barregen en secundaris: blau + groc = verd, vermell + groc = taronja, vermell + blau = violeta. El blanc aclareix un color.", Area.Physics, "Physics: light, pigments and colour|Física: luz, pigmentos y color|Physique : lumière, pigments et couleur|Física: llum, pigments i color", "prep"),
                    C("quantity", "Calculating the paint|Calcular la pintura|Calculer la peinture|Calcular la pintura", "Area = length × height (minus doors and windows). With about 10 m² per litre per coat, litres = area × coats ÷ 10.|Superficie = largo × alto (menos puertas y ventanas). Con unos 10 m² por litro y mano, litros = superficie × manos ÷ 10.|Surface = longueur × hauteur (moins portes et fenêtres). Avec environ 10 m² par litre et par couche, litres = surface × couches ÷ 10.|Superfície = llargada × alçada (menys portes i finestres). Amb uns 10 m² per litre i mà, litres = superfície × mans ÷ 10.", Area.Mathematics, "Mathematics: area and proportions|Matemáticas: área y proporciones|Mathématiques : aire et proportions|Matemàtiques: àrea i proporcions", "prep"),
                    C("apply", "Applying the paint|Aplicar la pintura|Appliquer la peinture|Aplicar la pintura", "Cut in the edges with a brush, then roll in a W and fill in; two thin coats are better than one thick coat; wait for the drying time between coats.|Perfila los bordes con brocha, después pasa el rodillo en W y rellena; dos manos finas son mejores que una gruesa; espera el tiempo de secado entre manos.|Fais les bords au pinceau, puis passe le rouleau en W et remplis ; deux couches fines valent mieux qu'une épaisse ; respecte le temps de séchage entre les couches.|Perfila les vores amb brotxa, després passa el corró en W i omple; dues mans fines són millors que una de gruixuda; espera el temps d'assecatge entre mans.", Area.Chemistry, "Chemistry: how paint dries (evaporation)|Química: cómo se seca la pintura (evaporación)|Chimie : comment sèche la peinture (évaporation)|Química: com s'asseca la pintura (evaporació)", "quantity"),
                    C("decor", "Light and decoration|Luz y decoración|Lumière et décoration|Llum i decoració", "Light colours reflect more light and make a room look bigger; warm colours (red, orange) feel cosy, cool colours (blue, green) feel calm; the 60-30-10 rule balances a room.|Los colores claros reflejan más luz y agrandan una habitación; los cálidos (rojo, naranja) dan sensación acogedora y los fríos (azul, verde) calma; la regla 60-30-10 equilibra un espacio.|Les couleurs claires réfléchissent plus de lumière et agrandissent une pièce ; les chaudes (rouge, orange) sont chaleureuses, les froides (bleu, vert) apaisantes ; la règle 60-30-10 équilibre une pièce.|Els colors clars reflecteixen més llum i fan l'habitació més gran; els càlids (vermell, taronja) són acollidors i els freds (blau, verd) calmants; la regla 60-30-10 equilibra un espai.", Area.Physics, "Physics: reflection of light|Física: reflexión de la luz|Physique : réflexion de la lumière|Física: reflexió de la llum", "colour", "apply"),
                ],
                [
                    Q("prep", 1, "Before painting a wall with small holes, what do you do?|Antes de pintar una pared con agujeritos, ¿qué haces?|Avant de peindre un mur avec de petits trous, que fais-tu ?|Abans de pintar una paret amb foradets, què fas?", "Fill them with filler and sand when dry|Taparlos con masilla y lijar cuando seque|Les reboucher avec de l'enduit et poncer une fois sec|Tapar-los amb massilla i llimar quan s'assequi", "Paint does not hide holes: it makes them more visible.|La pintura no esconde los agujeros: los hace más visibles.|La peinture ne cache pas les trous : elle les rend plus visibles.|La pintura no amaga els forats: els fa més visibles.", "Paint over them|Pintar encima|Peindre par-dessus|Pintar-hi a sobre", "Put stickers on them|Ponerles pegatinas|Mettre des autocollants|Posar-hi adhesius", "Wet the wall|Mojar la pared|Mouiller le mur|Mullar la paret"),
                    Q("prep", 2, "What is masking tape for?|¿Para qué sirve la cinta de carrocero?|À quoi sert le ruban de masquage ?|Per a què serveix la cinta de carrosser?", "To protect edges and get clean lines|Para proteger bordes y conseguir líneas limpias|À protéger les bords et obtenir des lignes nettes|Per protegir vores i aconseguir línies netes", "Remove it before the paint is fully dry so it does not tear the film.|Quítala antes de que la pintura esté seca del todo para no arrancar la capa.|Retire-le avant que la peinture soit complètement sèche pour ne pas arracher le film.|Treu-la abans que la pintura estigui seca del tot per no arrencar la capa.", "To hang pictures|Para colgar cuadros|À accrocher des tableaux|Per penjar quadres", "To dry the paint|Para secar la pintura|À sécher la peinture|Per assecar la pintura", "To mix colours|Para mezclar colores|À mélanger les couleurs|Per barrejar colors"),
                    Q("prep", 3, "Why do you apply primer to new plaster?|¿Por qué se da imprimación al yeso nuevo?|Pourquoi applique-t-on une sous-couche sur un plâtre neuf ?|Per què es dona imprimació al guix nou?", "It is porous: the primer seals it so the paint does not soak in unevenly|Es poroso: la imprimación lo sella para que la pintura no se absorba de forma irregular|Il est poreux : la sous-couche le bouche pour que la peinture ne soit pas absorbée de façon irrégulière|És porós: la imprimació el segella perquè la pintura no s'absorbeixi de manera irregular", "Without primer you would need more coats and get patches.|Sin imprimación necesitarías más manos y saldrían manchas.|Sans sous-couche, il faudrait plus de couches et il y aurait des taches.|Sense imprimació necessitaries més mans i sortirien taques.", "To change its colour|Para cambiar su color|Pour changer sa couleur|Per canviar-ne el color", "To make it heavier|Para que pese más|Pour l'alourdir|Perquè pesi més", "It is decoration|Es decoración|C'est de la décoration|És decoració"),
                    Q("colour", 1, "Which colour do you get by mixing blue and yellow paint?|¿Qué color sale al mezclar pintura azul y amarilla?|Quelle couleur obtiens-tu en mélangeant de la peinture bleue et jaune ?|Quin color surt en barrejar pintura blava i groga?", "Green|Verde|Vert|Verd", "Blue and yellow are primaries; green is a secondary colour.|El azul y el amarillo son primarios; el verde es un color secundario.|Le bleu et le jaune sont primaires ; le vert est une couleur secondaire.|El blau i el groc són primaris; el verd és un color secundari.", "Orange|Naranja|Orange|Taronja", "Violet|Violeta|Violet|Violeta", "Brown|Marrón|Marron|Marró"),
                    Q("colour", 2, "How do you make a light blue from dark blue paint?|¿Cómo haces un azul claro a partir de pintura azul oscura?|Comment obtenir un bleu clair à partir de peinture bleu foncé ?|Com fas un blau clar a partir de pintura blava fosca?", "Add white|Añadir blanco|Ajouter du blanc|Afegir blanc", "Adding white makes a tint; adding black makes a shade.|Añadir blanco aclara; añadir negro oscurece.|Ajouter du blanc éclaircit ; ajouter du noir assombrit.|Afegir blanc aclareix; afegir negre enfosqueix.", "Add black|Añadir negro|Ajouter du noir|Afegir negre", "Add water only|Añadir solo agua|Ajouter seulement de l'eau|Afegir només aigua", "Add red|Añadir rojo|Ajouter du rouge|Afegir vermell"),
                    Q("colour", 3, "Why does a red wall look red?|¿Por qué una pared roja se ve roja?|Pourquoi un mur rouge paraît-il rouge ?|Per què una paret vermella es veu vermella?", "Its pigment absorbs the other colours of light and reflects red|Su pigmento absorbe los otros colores de la luz y refleja el rojo|Son pigment absorbe les autres couleurs de la lumière et renvoie le rouge|El seu pigment absorbeix els altres colors de la llum i reflecteix el vermell", "White light contains all colours; a pigment keeps some and sends back others.|La luz blanca tiene todos los colores; un pigmento se queda unos y devuelve otros.|La lumière blanche contient toutes les couleurs ; un pigment en garde certaines et renvoie les autres.|La llum blanca té tots els colors; un pigment se'n queda uns i en retorna d'altres.", "It produces red light|Produce luz roja|Il produit de la lumière rouge|Produeix llum vermella", "It absorbs red|Absorbe el rojo|Il absorbe le rouge|Absorbeix el vermell", "Because of the temperature|Por la temperatura|À cause de la température|Per la temperatura"),
                    Q("quantity", 1, "A wall is 4 m long and 2.5 m high. What is its area?|Una pared mide 4 m de largo y 2,5 m de alto. ¿Cuál es su superficie?|Un mur mesure 4 m de long et 2,5 m de haut. Quelle est sa surface ?|Una paret fa 4 m de llarg i 2,5 m d'alt. Quina és la seva superfície?", "10 m²", "4 × 2.5 = 10 m².|4 × 2,5 = 10 m².|4 × 2,5 = 10 m².|4 × 2,5 = 10 m².", "6.5 m²|6,5 m²|6,5 m²|6,5 m²", "13 m²", "100 m²"),
                    Q("quantity", 2, "A paint covers 10 m² per litre. How many litres for 30 m² with 2 coats?|Una pintura cubre 10 m² por litro. ¿Cuántos litros para 30 m² a 2 manos?|Une peinture couvre 10 m² par litre. Combien de litres pour 30 m² en 2 couches ?|Una pintura cobreix 10 m² per litre. Quants litres per a 30 m² a 2 mans?", "6 litres|6 litros|6 litres|6 litres", "30 × 2 = 60 m² to cover; 60 ÷ 10 = 6 L.|30 × 2 = 60 m² a cubrir; 60 ÷ 10 = 6 L.|30 × 2 = 60 m² à couvrir ; 60 ÷ 10 = 6 L.|30 × 2 = 60 m² a cobrir; 60 ÷ 10 = 6 L.", "3 litres|3 litros|3 litres|3 litres", "60 litres|60 litros|60 litres|60 litres", "20 litres|20 litros|20 litres|20 litres"),
                    Q("quantity", 3, "A 12 m² wall has a 2 m² door that you will not paint. How much area do you paint?|Una pared de 12 m² tiene una puerta de 2 m² que no vas a pintar. ¿Cuánta superficie pintas?|Un mur de 12 m² a une porte de 2 m² que tu ne peindras pas. Quelle surface peins-tu ?|Una paret de 12 m² té una porta de 2 m² que no pintaràs. Quanta superfície pintes?", "10 m²", "Subtract openings: 12 − 2 = 10 m².|Resta los huecos: 12 − 2 = 10 m².|On retire les ouvertures : 12 − 2 = 10 m².|Resta els forats: 12 − 2 = 10 m².", "14 m²", "24 m²", "6 m²"),
                    Q("apply", 1, "Which is better for an even finish?|¿Qué es mejor para un acabado uniforme?|Qu'est-ce qui est mieux pour une finition uniforme ?|Què és millor per a un acabat uniforme?", "Two thin coats|Dos manos finas|Deux couches fines|Dues mans fines", "Thin coats dry evenly and do not drip.|Las manos finas secan de forma regular y no gotean.|Les couches fines sèchent uniformément et ne coulent pas.|Les mans fines s'assequen de manera regular i no degoten.", "One very thick coat|Una mano muy gruesa|Une couche très épaisse|Una mà molt gruixuda", "Paint with your fingers|Pintar con los dedos|Peindre avec les doigts|Pintar amb els dits", "Paint without stirring|Pintar sin remover|Peindre sans remuer|Pintar sense remenar"),
                    Q("apply", 2, "Why must you wait between two coats?|¿Por qué hay que esperar entre dos manos?|Pourquoi faut-il attendre entre deux couches ?|Per què cal esperar entre dues mans?", "The first coat must dry, or the roller pulls it off|La primera mano debe secarse; si no, el rodillo la arranca|La première couche doit sécher, sinon le rouleau l'arrache|La primera mà s'ha d'assecar; si no, el corró l'arrenca", "Water-based paint dries as its water evaporates; the label gives the time.|La pintura al agua se seca cuando se evapora su agua; la etiqueta da el tiempo.|La peinture à l'eau sèche quand son eau s'évapore ; l'étiquette donne le temps.|La pintura a l'aigua s'asseca quan se n'evapora l'aigua; l'etiqueta dona el temps.", "To rest your arms|Para descansar los brazos|Pour reposer les bras|Per descansar els braços", "The colour changes|Cambia el color|La couleur change|Canvia el color", "It is not necessary|No hace falta|Ce n'est pas nécessaire|No cal"),
                    Q("apply", 3, "Why does paint dry faster in a warm, ventilated room?|¿Por qué la pintura se seca antes en una habitación templada y ventilada?|Pourquoi la peinture sèche-t-elle plus vite dans une pièce tempérée et aérée ?|Per què la pintura s'asseca abans en una habitació temperada i ventilada?", "Warmth and moving air speed up evaporation|El calor y el aire en movimiento aceleran la evaporación|La chaleur et l'air qui circule accélèrent l'évaporation|La calor i l'aire en moviment acceleren l'evaporació", "Like washing on a line: humid, cold air dries more slowly.|Como la ropa tendida: el aire húmedo y frío seca más despacio.|Comme le linge étendu : l'air humide et froid sèche plus lentement.|Com la roba estesa: l'aire humit i fred asseca més a poc a poc.", "Light melts the paint|La luz derrite la pintura|La lumière fait fondre la peinture|La llum fon la pintura", "Paint likes music|A la pintura le gusta la música|La peinture aime la musique|A la pintura li agrada la música", "It dries slower|Se seca más despacio|Elle sèche plus lentement|S'asseca més a poc a poc"),
                    Q("decor", 1, "Which colours make a small room look bigger?|¿Qué colores hacen que una habitación pequeña parezca más grande?|Quelles couleurs font paraître une petite pièce plus grande ?|Quins colors fan que una habitació petita sembli més gran?", "Light colours|Colores claros|Les couleurs claires|Colors clars", "They reflect more light, so the space looks open.|Reflejan más luz y el espacio parece abierto.|Elles renvoient plus de lumière et l'espace paraît ouvert.|Reflecteixen més llum i l'espai sembla obert.", "Very dark colours|Colores muy oscuros|Les couleurs très foncées|Colors molt foscos", "Black only|Solo negro|Seulement le noir|Només negre", "Colour does not change it|El color no influye|La couleur n'y change rien|El color no hi influeix"),
                    Q("decor", 2, "Which of these is a 'cool' colour?|¿Cuál de estos es un color «frío»?|Laquelle de ces couleurs est « froide » ?|Quin d'aquests és un color «fred»?", "Blue|Azul|Bleu|Blau", "Blues and greens feel calm and fresh; reds and oranges feel warm.|Los azules y verdes transmiten calma y frescor; los rojos y naranjas calidez.|Les bleus et les verts sont calmes et frais ; les rouges et les orangés sont chaleureux.|Els blaus i verds transmeten calma i frescor; els vermells i taronges calidesa.", "Orange|Naranja|Orange|Taronja", "Red|Rojo|Rouge|Vermell", "Yellow|Amarillo|Jaune|Groc"),
                    Q("decor", 3, "In the 60-30-10 rule, what is the 10 %?|En la regla 60-30-10, ¿qué es el 10 %?|Dans la règle 60-30-10, que représentent les 10 % ?|A la regla 60-30-10, què és el 10 %?", "An accent colour for details|Un color de acento para los detalles|Une couleur d'accent pour les détails|Un color d'accent per als detalls", "60 % main colour (walls), 30 % secondary (furniture, textiles), 10 % accent (cushions, objects).|60 % color principal (paredes), 30 % secundario (muebles, textiles), 10 % acento (cojines, objetos).|60 % couleur principale (murs), 30 % secondaire (meubles, textiles), 10 % accent (coussins, objets).|60 % color principal (parets), 30 % secundari (mobles, tèxtils), 10 % accent (coixins, objectes).", "The walls|Las paredes|Les murs|Les parets", "The floor|El suelo|Le sol|El terra", "The ceiling only|Solo el techo|Seulement le plafond|Només el sostre"),
                ]),
            new("trade-beekeeping", "🐝", "sun",
                Txt.Of("Beekeeping|Apicultura|Apiculture|Apicultura"),
                Txt.Of("The life of a hive: the queen, workers and drones, how bees talk, the hexagons of the comb, how honey is made and how to care for bees.|La vida de una colmena: la reina, las obreras y los zánganos, cómo se comunican las abejas, los hexágonos del panal, cómo se hace la miel y cómo cuidar las abejas.|La vie d'une ruche : la reine, les ouvrières et les faux bourdons, comment les abeilles communiquent, les hexagones des rayons, comment se fait le miel et comment soigner les abeilles.|La vida d'un rusc: la reina, les obreres i els abellots, com es comuniquen les abelles, els hexàgons de la bresca, com es fa la mel i com tenir cura de les abelles."),
                Txt.Of("Never open a hive without a beekeeper and full protective clothing. If you are allergic to stings, stay away from hives.|Nunca abras una colmena sin un apicultor y el traje de protección completo. Si eres alérgico a las picaduras, no te acerques a las colmenas.|N'ouvre jamais une ruche sans apiculteur et sans tenue de protection complète. Si tu es allergique aux piqûres, reste loin des ruches.|No obris mai un rusc sense un apicultor i el vestit de protecció complet. Si ets al·lèrgic a les picades, no t'acostis als ruscs."),
                [
                    C("colony", "The colony|La colonia|La colonie|La colònia", "A hive has one queen that lays the eggs, thousands of female workers that do every job, and some male drones whose job is to mate with a queen.|Una colmena tiene una reina que pone los huevos, miles de obreras hembra que hacen todos los trabajos y algunos zánganos machos que sirven para fecundar a una reina.|Une ruche a une reine qui pond les œufs, des milliers d'ouvrières femelles qui font tous les travaux et quelques faux bourdons mâles qui servent à féconder une reine.|Un rusc té una reina que pon els ous, milers d'obreres femella que fan totes les feines i alguns abellots mascles que serveixen per fecundar una reina.", Area.Biology, "Biology: social insects|Biología: insectos sociales|Biologie : les insectes sociaux|Biologia: insectes socials"),
                    C("dance", "The bee dance|La danza de las abejas|La danse des abeilles|La dansa de les abelles", "A forager that finds flowers does a waggle dance: the angle shows the direction compared to the Sun and the length of the waggle shows the distance.|Una pecoreadora que encuentra flores hace una danza de meneo: el ángulo indica la dirección respecto al Sol y la duración del meneo, la distancia.|Une butineuse qui trouve des fleurs fait une danse frétillante : l'angle indique la direction par rapport au Soleil et la durée du frétillement la distance.|Una pecorejadora que troba flors fa una dansa de bellugueig: l'angle indica la direcció respecte al Sol i la durada del bellugueig, la distància.", Area.Biology, "Biology: animal communication (Karl von Frisch)|Biología: comunicación animal (Karl von Frisch)|Biologie : la communication animale (Karl von Frisch)|Biologia: comunicació animal (Karl von Frisch)", "colony"),
                    C("comb", "Hexagons and wax|Hexágonos y cera|Hexagones et cire|Hexàgons i cera", "Bees make wax with glands on their abdomen and build hexagonal cells: hexagons fill the plane with no gaps and use little wax for a lot of space.|Las abejas producen cera con unas glándulas del abdomen y construyen celdas hexagonales: los hexágonos cubren el plano sin huecos y usan poca cera para mucho espacio.|Les abeilles produisent la cire avec des glandes de l'abdomen et construisent des cellules hexagonales : les hexagones pavent le plan sans trou et utilisent peu de cire pour beaucoup d'espace.|Les abelles produeixen cera amb unes glàndules de l'abdomen i construeixen cel·les hexagonals: els hexàgons cobreixen el pla sense forats i fan servir poca cera per a molt espai.", Area.Mathematics, "Mathematics: tessellations and hexagons|Matemáticas: teselaciones y hexágonos|Mathématiques : pavages et hexagones|Matemàtiques: tessel·lacions i hexàgons", "colony"),
                    C("honey", "From nectar to honey|Del néctar a la miel|Du nectar au miel|Del nectar a la mel", "Bees collect nectar, add enzymes and fan their wings to evaporate water until honey has less than about 18–20 % water; so much sugar keeps microbes from growing.|Las abejas recogen néctar, le añaden enzimas y aletean para evaporar agua hasta que la miel tiene menos de un 18–20 % de agua; tanto azúcar impide que crezcan microbios.|Les abeilles récoltent le nectar, ajoutent des enzymes et ventilent pour évaporer l'eau jusqu'à ce que le miel contienne moins d'environ 18–20 % d'eau ; tant de sucre empêche les microbes de se développer.|Les abelles recullen nectar, hi afegeixen enzims i aletegen per evaporar aigua fins que la mel té menys d'un 18–20 % d'aigua; tant de sucre impedeix que creixin microbis.", Area.Chemistry, "Chemistry: sugars, enzymes and evaporation|Química: azúcares, enzimas y evaporación|Chimie : sucres, enzymes et évaporation|Química: sucres, enzims i evaporació", "dance"),
                    C("care", "Caring for the hive|Cuidar la colmena|Prendre soin de la ruche|Tenir cura del rusc", "The beekeeper calms bees with a smoker, checks the frames, watches for parasites like the Varroa mite and leaves enough honey for winter. Bees pollinate many of our crops.|El apicultor calma a las abejas con el ahumador, revisa los cuadros, vigila parásitos como el ácaro varroa y deja miel suficiente para el invierno. Las abejas polinizan muchos de nuestros cultivos.|L'apiculteur calme les abeilles avec l'enfumoir, inspecte les cadres, surveille les parasites comme l'acarien varroa et laisse assez de miel pour l'hiver. Les abeilles pollinisent beaucoup de nos cultures.|L'apicultor calma les abelles amb el fumador, revisa els quadres, vigila paràsits com l'àcar varroa i deixa prou mel per a l'hivern. Les abelles pol·linitzen molts dels nostres cultius.", Area.Biology, "Biology: pollination and ecosystems|Biología: polinización y ecosistemas|Biologie : pollinisation et écosystèmes|Biologia: pol·linització i ecosistemes", "honey"),
                ],
                [
                    Q("colony", 1, "How many queens does a normal hive have?|¿Cuántas reinas tiene una colmena normal?|Combien de reines a une ruche normale ?|Quantes reines té un rusc normal?", "One|Una|Une|Una", "She lays all the eggs: up to about 2,000 a day in spring.|Ella pone todos los huevos: hasta unos 2000 al día en primavera.|Elle pond tous les œufs : jusqu'à environ 2 000 par jour au printemps.|Ella pon tots els ous: fins a uns 2.000 al dia a la primavera.", "Ten|Diez|Dix|Deu", "None|Ninguna|Aucune|Cap", "Hundreds|Cientos|Des centaines|Centenars"),
                    Q("colony", 2, "Are worker bees male or female?|¿Las abejas obreras son machos o hembras?|Les abeilles ouvrières sont-elles mâles ou femelles ?|Les abelles obreres són mascles o femelles?", "Female|Hembras|Femelles|Femelles", "Workers are females that do not reproduce; the males are the drones.|Las obreras son hembras que no se reproducen; los machos son los zánganos.|Les ouvrières sont des femelles qui ne se reproduisent pas ; les mâles sont les faux bourdons.|Les obreres són femelles que no es reprodueixen; els mascles són els abellots.", "Male|Machos|Mâles|Mascles", "Both, half and half|Mitad y mitad|Moitié-moitié|Meitat i meitat", "Neither|Ninguno de los dos|Ni l'un ni l'autre|Cap dels dos"),
                    Q("colony", 3, "What makes a female larva become a queen instead of a worker?|¿Qué hace que una larva hembra se convierta en reina en lugar de obrera?|Qu'est-ce qui fait qu'une larve femelle devient reine plutôt qu'ouvrière ?|Què fa que una larva femella es converteixi en reina en lloc d'obrera?", "She is fed only royal jelly|Que la alimentan solo con jalea real|Elle est nourrie uniquement de gelée royale|Que l'alimenten només amb gelea reial", "Same genes, different food: a clear example of how environment changes development.|Mismos genes, distinta comida: un ejemplo claro de cómo el ambiente cambia el desarrollo.|Mêmes gènes, nourriture différente : un bel exemple de l'effet de l'environnement sur le développement.|Mateixos gens, menjar diferent: un exemple clar de com l'ambient canvia el desenvolupament.", "She is born from a bigger egg|Nace de un huevo más grande|Elle naît d'un œuf plus gros|Neix d'un ou més gran", "She is the oldest|Es la más vieja|C'est la plus vieille|És la més vella", "She fights the others|Pelea con las demás|Elle se bat contre les autres|Es baralla amb les altres"),
                    Q("dance", 1, "How does a bee tell the others where the flowers are?|¿Cómo indica una abeja a las demás dónde están las flores?|Comment une abeille indique-t-elle aux autres où sont les fleurs ?|Com indica una abella a les altres on són les flors?", "With a dance|Con una danza|Par une danse|Amb una dansa", "Karl von Frisch decoded the waggle dance and won the Nobel Prize in 1973.|Karl von Frisch descifró la danza y ganó el Premio Nobel en 1973.|Karl von Frisch a décodé la danse frétillante et a reçu le prix Nobel en 1973.|Karl von Frisch va desxifrar la dansa i va guanyar el Premi Nobel el 1973.", "By singing|Cantando|En chantant|Cantant", "With a map|Con un mapa|Avec une carte|Amb un mapa", "It does not tell them|No se lo dice|Elle ne le dit pas|No els ho diu"),
                    Q("dance", 2, "In the waggle dance, what does the angle of the dance show?|En la danza de meneo, ¿qué indica el ángulo?|Dans la danse frétillante, qu'indique l'angle ?|A la dansa de bellugueig, què indica l'angle?", "The direction of the food compared to the Sun|La dirección de la comida respecto al Sol|La direction de la nourriture par rapport au Soleil|La direcció del menjar respecte al Sol", "Straight up on the comb means 'towards the Sun'.|Hacia arriba en el panal significa «hacia el Sol».|Vers le haut sur le rayon veut dire « vers le Soleil ».|Cap amunt a la bresca vol dir «cap al Sol».", "The colour of the flowers|El color de las flores|La couleur des fleurs|El color de les flors", "The weather tomorrow|El tiempo de mañana|La météo de demain|El temps de demà", "The age of the bee|La edad de la abeja|L'âge de l'abeille|L'edat de l'abella"),
                    Q("dance", 3, "In the waggle dance, a longer waggle run means…|En la danza de meneo, un meneo más largo significa…|Dans la danse frétillante, un frétillement plus long signifie…|A la dansa de bellugueig, un bellugueig més llarg vol dir…", "the food is further away|que la comida está más lejos|que la nourriture est plus loin|que el menjar és més lluny", "The duration of the waggle grows with the distance to the flowers.|La duración del meneo crece con la distancia a las flores.|La durée du frétillement augmente avec la distance aux fleurs.|La durada del bellugueig creix amb la distància a les flors.", "there is more food|que hay más comida|qu'il y a plus de nourriture|que hi ha més menjar", "danger|peligro|un danger|perill", "the flowers are red|que las flores son rojas|que les fleurs sont rouges|que les flors són vermelles"),
                    Q("comb", 1, "What shape are the cells of a honeycomb?|¿Qué forma tienen las celdas de un panal?|Quelle forme ont les cellules d'un rayon de miel ?|Quina forma tenen les cel·les d'una bresca?", "Hexagon|Hexágono|Hexagone|Hexàgon", "Six equal sides, joined with no gaps.|Seis lados iguales, unidos sin huecos.|Six côtés égaux, assemblés sans trous.|Sis costats iguals, units sense forats.", "Circle|Círculo|Cercle|Cercle", "Triangle|Triángulo|Triangle|Triangle", "Star|Estrella|Étoile|Estrella"),
                    Q("comb", 2, "Where does the wax of the comb come from?|¿De dónde sale la cera del panal?|D'où vient la cire des rayons ?|D'on surt la cera de la bresca?", "From glands on the abdomen of young worker bees|De unas glándulas del abdomen de las obreras jóvenes|De glandes de l'abdomen des jeunes ouvrières|D'unes glàndules de l'abdomen de les obreres joves", "They make it from the sugar of honey: about 6–8 kg of honey per kg of wax.|La producen a partir del azúcar de la miel: unos 6–8 kg de miel por kg de cera.|Elles la fabriquent avec le sucre du miel : environ 6–8 kg de miel par kg de cire.|La produeixen a partir del sucre de la mel: uns 6–8 kg de mel per kg de cera.", "From flowers|De las flores|Des fleurs|De les flors", "From tree bark|De la corteza de los árboles|De l'écorce des arbres|De l'escorça dels arbres", "The beekeeper brings it|La trae el apicultor|L'apiculteur l'apporte|La porta l'apicultor"),
                    Q("comb", 3, "Why are hexagons a good shape for the comb, rather than circles?|¿Por qué el hexágono es buena forma para el panal y no el círculo?|Pourquoi l'hexagone est-il une bonne forme pour le rayon plutôt que le cercle ?|Per què l'hexàgon és una bona forma per a la bresca i no el cercle?", "They fill the space with no gaps and use the least wall for their area|Llenan el espacio sin huecos y usan el mínimo de pared para su superficie|Ils remplissent l'espace sans trous et utilisent le moins de paroi pour leur surface|Omplen l'espai sense forats i fan servir el mínim de paret per a la seva superfície", "Circles leave gaps; triangles and squares tile too, but need more wall for the same area.|Los círculos dejan huecos; triángulos y cuadrados también encajan, pero necesitan más pared para la misma superficie.|Les cercles laissent des trous ; triangles et carrés pavent aussi, mais demandent plus de paroi pour la même surface.|Els cercles deixen forats; triangles i quadrats també encaixen, però necessiten més paret per a la mateixa superfície.", "Bees cannot make curves|Las abejas no saben hacer curvas|Les abeilles ne savent pas faire de courbes|Les abelles no saben fer corbes", "It is prettier|Es más bonito|C'est plus joli|És més bonic", "Hexagons hold less honey|Los hexágonos guardan menos miel|Les hexagones contiennent moins de miel|Els hexàgons guarden menys mel"),
                    Q("honey", 1, "What do bees make honey from?|¿Con qué hacen la miel las abejas?|Avec quoi les abeilles font-elles le miel ?|Amb què fan la mel les abelles?", "Flower nectar|Néctar de las flores|Le nectar des fleurs|Nectar de les flors", "Nectar is a sugary liquid; bees turn it into honey in the hive.|El néctar es un líquido azucarado; las abejas lo transforman en miel en la colmena.|Le nectar est un liquide sucré ; les abeilles le transforment en miel dans la ruche.|El nectar és un líquid ensucrat; les abelles el transformen en mel al rusc.", "Leaves|Hojas|Des feuilles|Fulles", "Water only|Solo agua|Seulement de l'eau|Només aigua", "Soil|Tierra|De la terre|Terra"),
                    Q("honey", 2, "Why do bees fan their wings over the cells of nectar?|¿Por qué las abejas aletean sobre las celdas de néctar?|Pourquoi les abeilles ventilent-elles au-dessus des cellules de nectar ?|Per què les abelles aletegen sobre les cel·les de nectar?", "To evaporate water and thicken it|Para evaporar agua y espesarlo|Pour évaporer l'eau et l'épaissir|Per evaporar aigua i espessir-lo", "Nectar can be over 70 % water; honey is under about 20 %.|El néctar puede tener más de un 70 % de agua; la miel, menos de un 20 %.|Le nectar peut contenir plus de 70 % d'eau ; le miel, moins d'environ 20 %.|El nectar pot tenir més d'un 70 % d'aigua; la mel, menys d'un 20 %.", "To dance|Para bailar|Pour danser|Per ballar", "To cool the queen only|Solo para refrescar a la reina|Seulement pour rafraîchir la reine|Només per refrescar la reina", "To make noise|Para hacer ruido|Pour faire du bruit|Per fer soroll"),
                    Q("honey", 3, "Why can honey keep for years without going bad?|¿Por qué la miel puede durar años sin estropearse?|Pourquoi le miel peut-il se conserver des années sans s'abîmer ?|Per què la mel pot durar anys sense fer-se malbé?", "So much sugar and so little water keep microbes from growing|Tanto azúcar y tan poca agua impiden que crezcan los microbios|Autant de sucre et si peu d'eau empêchent les microbes de se développer|Tant de sucre i tan poca aigua impedeixen que creixin els microbis", "It is also slightly acidic. Keep it closed: it absorbs moisture from the air.|Además es algo ácida. Guárdala cerrada: absorbe la humedad del aire.|Il est aussi un peu acide. Garde-le fermé : il absorbe l'humidité de l'air.|A més és una mica àcida. Guarda-la tancada: absorbeix la humitat de l'aire.", "It is kept in the fridge|Se guarda en la nevera|On le garde au frigo|Es guarda a la nevera", "Bees add salt|Las abejas le añaden sal|Les abeilles y ajoutent du sel|Les abelles hi afegeixen sal", "It does go bad quickly|Sí se estropea rápido|Il s'abîme vite|Sí que es fa malbé ràpid"),
                    Q("care", 1, "What does the beekeeper use to calm the bees?|¿Qué usa el apicultor para calmar a las abejas?|Qu'utilise l'apiculteur pour calmer les abeilles ?|Què fa servir l'apicultor per calmar les abelles?", "A smoker|Un ahumador|Un enfumoir|Un fumador", "Cool smoke hides the alarm scent and the bees eat honey instead of defending.|El humo frío tapa el olor de alarma y las abejas comen miel en lugar de defenderse.|La fumée froide masque l'odeur d'alarme et les abeilles mangent du miel au lieu de se défendre.|El fum fred tapa l'olor d'alarma i les abelles mengen mel en lloc de defensar-se.", "A whistle|Un silbato|Un sifflet|Un xiulet", "Water spray only|Solo agua pulverizada|Seulement un vaporisateur d'eau|Només aigua polvoritzada", "Loud music|Música fuerte|De la musique forte|Música forta"),
                    Q("care", 2, "Why are bees so important for agriculture?|¿Por qué las abejas son tan importantes para la agricultura?|Pourquoi les abeilles sont-elles si importantes pour l'agriculture ?|Per què les abelles són tan importants per a l'agricultura?", "They pollinate flowers so that many crops make fruit|Polinizan las flores para que muchos cultivos den fruto|Elles pollinisent les fleurs pour que beaucoup de cultures donnent des fruits|Pol·linitzen les flors perquè molts cultius donin fruit", "Apples, almonds, strawberries and many more depend on pollinators.|Manzanas, almendras, fresas y muchos más dependen de los polinizadores.|Pommes, amandes, fraises et bien d'autres dépendent des pollinisateurs.|Pomes, ametlles, maduixes i molts més depenen dels pol·linitzadors.", "They eat pests|Se comen las plagas|Elles mangent les nuisibles|Es mengen les plagues", "They water the plants|Riegan las plantas|Elles arrosent les plantes|Reguen les plantes", "They are not important|No son importantes|Elles ne sont pas importantes|No són importants"),
                    Q("care", 3, "What is Varroa?|¿Qué es la varroa?|Qu'est-ce que le varroa ?|Què és la varroa?", "A parasitic mite that weakens bees and spreads viruses|Un ácaro parásito que debilita a las abejas y transmite virus|Un acarien parasite qui affaiblit les abeilles et transmet des virus|Un àcar paràsit que debilita les abelles i transmet virus", "Beekeepers check and treat hives regularly against it.|Los apicultores revisan y tratan las colmenas contra él con regularidad.|Les apiculteurs contrôlent et traitent régulièrement les ruches contre lui.|Els apicultors revisen i tracten els ruscs contra ell regularment.", "A type of flower|Un tipo de flor|Une sorte de fleur|Un tipus de flor", "A kind of honey|Un tipo de miel|Une sorte de miel|Un tipus de mel", "The beekeeper's suit|El traje del apicultor|La tenue de l'apiculteur|El vestit de l'apicultor"),
                ]),
        ];
    }
}
